<?php
$viewMode = ($_GET['view'] ?? '') === 'compact' ? 'compact' : 'analytics';
$editId = filter_input(INPUT_GET, 'edit', FILTER_VALIDATE_INT);
$editLand = null;
if ($editId) { $editStmt = db()->prepare('SELECT * FROM terrains WHERE id=:id'); $editStmt->execute(['id'=>$editId]); $editLand = $editStmt->fetch() ?: null; }
$stats = db()->query("SELECT COUNT(*) AS total, SUM(statut='disponible') AS available, SUM(statut='reserve') AS reserved, SUM(vues) AS views FROM terrains")->fetch();
$requestStats = db()->query("SELECT COUNT(*) AS total, SUM(statut='non_lu') AS unread FROM demandes_clients")->fetch();
$landRows = db()->query('SELECT * FROM terrains ORDER BY date_publication DESC LIMIT 100')->fetchAll();
$topViewed = db()->query('SELECT titre, vues FROM terrains ORDER BY vues DESC, date_publication DESC LIMIT 5')->fetchAll();
$maxViews = max(1, (int) ($topViewed[0]['vues'] ?? 0));
$submissions = db()->query('SELECT * FROM soumissions_vendeurs ORDER BY date_soumission DESC LIMIT 100')->fetchAll();
$requests = db()->query('SELECT d.*, t.titre AS terrain_titre FROM demandes_clients d LEFT JOIN terrains t ON t.id=d.terrain_id ORDER BY d.date_demande DESC LIMIT 100')->fetchAll();
?>
<section class="admin-shell <?= $viewMode === 'compact' ? 'admin-compact' : '' ?>">
  <div class="admin-head"><div><span class="eyebrow">SG SERVICES · ESPACE SÉCURISÉ</span><h1>Bonjour, <?= e($_SESSION['user']['nom']) ?>.</h1><p>Votre activité immobilière, en un seul endroit.</p></div><div class="admin-head-actions"><a class="mode-link <?= $viewMode === 'analytics' ? 'active' : '' ?>" href="?page=admin&view=analytics">Analyse</a><a class="mode-link <?= $viewMode === 'compact' ? 'active' : '' ?>" href="?page=admin&view=compact">Mobile</a><form method="post" action="?page=logout"><?= csrf_field() ?><button class="text-link">Déconnexion ↗</button></form></div></div>
  <div class="admin-section-title"><a class="button button-green" href="?page=admin&new=1">Ajouter une fiche complète <span>↗</span></a></div>
  <div class="admin-section-title"><a class="button button-green" href="?page=admin&new=1">Ajouter une fiche complète <span>↗</span></a></div>
  <?php if ($viewMode === 'analytics'): ?><section class="views-chart"><div class="chart-heading"><div><span class="eyebrow">INTÉRÊT DES VISITEURS</span><h2>Terrains les plus consultés</h2></div><span>Vues cumulées</span></div><?php if ($topViewed): foreach ($topViewed as $viewed): $barWidth = min(100, (int) round(((int)$viewed['vues'] / $maxViews) * 100)); ?><div class="chart-row"><span><?= e($viewed['titre']) ?></span><div class="chart-track"><i style="width:<?= $barWidth ?>%"></i></div><strong><?= (int)$viewed['vues'] ?></strong></div><?php endforeach; else: ?><p class="admin-empty">Les statistiques apparaîtront lorsque des terrains auront été consultés.</p><?php endif; ?></section><?php endif; ?>
  <div class="kpi-grid"><div class="kpi"><span>Terrains au catalogue</span><strong><?= (int)($stats['total'] ?? 0) ?></strong><small><?= (int)($stats['available'] ?? 0) ?> disponibles · <?= (int)($stats['reserved'] ?? 0) ?> réservés</small></div><div class="kpi"><span>Vues des fiches</span><strong><?= number_format((int)($stats['views'] ?? 0),0,',',' ') ?></strong><small>Depuis la mise en ligne</small></div><div class="kpi"><span>Demandes reçues</span><strong><?= (int)($requestStats['total'] ?? 0) ?></strong><small><?= (int)($requestStats['unread'] ?? 0) ?> à traiter</small></div><div class="kpi"><span>Propositions vendeurs</span><strong><?= count(array_filter($submissions, static fn($row) => $row['statut_traitement'] === 'nouveau')) ?></strong><small>Nouvelles propositions</small></div></div>
  <section class="admin-section"><div class="admin-section-title"><div><span class="eyebrow">CATALOGUE</span><h2><?= $editLand ? 'Modifier le terrain' : 'Ajouter un terrain' ?></h2></div></div><form class="admin-land-form" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="save_land"><input type="hidden" name="id" value="<?= (int)($editLand['id'] ?? 0) ?>"><label>Titre<input name="titre" required maxlength="180" value="<?= e($editLand['titre'] ?? '') ?>"></label><label>Commune / zone<input name="zone_commune" required maxlength="120" value="<?= e($editLand['zone_commune'] ?? '') ?>"></label><label>Prix (FCFA)<input type="number" min="0" step="1" name="prix" required value="<?= e($editLand['prix'] ?? '') ?>"></label><label>Superficie (m²)<input type="number" min="0.01" step="0.01" name="superficie" required value="<?= e($editLand['superficie'] ?? '') ?>"></label><label>Statut<select name="statut"><option value="disponible" <?= ($editLand['statut'] ?? '')==='disponible'?'selected':'' ?>>Disponible</option><option value="reserve" <?= ($editLand['statut'] ?? '')==='reserve'?'selected':'' ?>>Réservé</option><option value="vendu" <?= ($editLand['statut'] ?? '')==='vendu'?'selected':'' ?>>Vendu</option></select></label><label>Statut juridique<select name="statut_juridique"><?php foreach (['À vérifier','Titre Foncier','ACD','Attestation Villageoise'] as $legal): ?><option <?= ($editLand['statut_juridique'] ?? 'À vérifier')===$legal?'selected':'' ?>><?= e($legal) ?></option><?php endforeach; ?></select></label><label>Latitude<input type="number" step="0.0000001" min="-90" max="90" name="latitude" required value="<?= e($editLand['latitude'] ?? '5.3600') ?>"></label><label>Longitude<input type="number" step="0.0000001" min="-180" max="180" name="longitude" required value="<?= e($editLand['longitude'] ?? '-4.0083') ?>"></label><label class="admin-span">Description<textarea name="description" rows="3" required><?= e($editLand['description'] ?? '') ?></textarea></label><label class="admin-span">Ajouter des photos<input type="file" name="photos[]" accept=".jpg,.jpeg,.png" multiple><small>JPG ou PNG, 8 Mo maximum par fichier.</small></label><div class="admin-span admin-form-actions"><button class="button button-green"><?= $editLand ? 'Enregistrer les modifications' : 'Publier le terrain' ?> <span>↗</span></button><?php if ($editLand): ?><a class="button button-outline" href="?page=admin">Annuler</a><?php endif; ?></div></form></section>
  <section class="admin-section"><div class="admin-section-title"><div><span class="eyebrow">GESTION DES OFFRES</span><h2>Terrains</h2></div></div><?php if ($landRows): ?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Terrain</th><th>Zone</th><th>Prix</th><th>Statut</th><th>Vues</th><th>Actions</th></tr></thead><tbody><?php foreach ($landRows as $land): ?><tr><td><strong><?= e($land['titre']) ?></strong></td><td><?= e($land['zone_commune']) ?></td><td><?= number_format((float)$land['prix'],0,',',' ') ?> FCFA</td><td><span class="status-pill <?= e($land['statut']) ?>"><?= e($land['statut']) ?></span></td><td><?= (int)$land['vues'] ?></td><td class="table-actions"><a href="?page=admin&edit=<?= (int)$land['id'] ?>">Modifier</a><form method="post" onsubmit="return confirm('Supprimer ce terrain ?')"><?= csrf_field() ?><input type="hidden" name="action" value="delete_land"><input type="hidden" name="id" value="<?= (int)$land['id'] ?>"><button class="danger-link">Supprimer</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="admin-empty">Aucun terrain publié. Utilisez le formulaire ci-dessus pour commencer.</p><?php endif; ?></section>
  <section class="admin-section"><div class="admin-section-title"><div><span class="eyebrow">NOUVELLES OPPORTUNITÉS</span><h2>Propositions de vendeurs</h2></div></div><?php if ($submissions): ?><div class="submission-list"><?php foreach ($submissions as $submission): ?><article class="submission-item"><div class="submission-main"><span class="status-pill <?= e($submission['statut_traitement']) ?>"><?= e(str_replace('_',' ',$submission['statut_traitement'])) ?></span><h3><?= e(ucfirst(str_replace('_',' ',$submission['type_bien']))) ?> · <?= e($submission['localisation']) ?></h3><p><?= e($submission['nom_proprietaire']) ?> · <?= e($submission['contact_whatsapp']) ?> · <?= number_format((float)$submission['prix_souhaite'],0,',',' ') ?> FCFA · <?= number_format((float)$submission['superficie'],0,',',' ') ?> m²</p><p><?= e($submission['description']) ?></p><small>Reçue le <?= e($submission['date_soumission']) ?></small><?php $submissionFiles = json_decode((string)$submission['fichiers_justificatifs'], true) ?: []; if ($submissionFiles): ?><p>Justificatifs : <?php foreach (array_keys($submissionFiles) as $fileIndex): ?><a href="?page=download&id=<?= (int)$submission['id'] ?>&file=<?= (int)$fileIndex ?>">Fichier <?= (int)$fileIndex + 1 ?> ↓</a> <?php endforeach; ?></p><?php endif; ?></div><div class="submission-actions"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="submission_status"><input type="hidden" name="id" value="<?= (int)$submission['id'] ?>"><select name="status" aria-label="Statut de la proposition"><option value="nouveau">Nouveau</option><option value="en_cours" <?= $submission['statut_traitement']==='en_cours'?'selected':'' ?>>En cours</option><option value="refuse" <?= $submission['statut_traitement']==='refuse'?'selected':'' ?>>Refusé</option><option value="accepte" <?= $submission['statut_traitement']==='accepte'?'selected':'' ?>>Accepté</option></select><button class="button button-outline">Mettre à jour</button></form><?php if ($submission['statut_traitement'] !== 'refuse' && empty($submission['terrain_id'])): ?><form method="post" onsubmit="return confirm('Convertir cette proposition en terrain disponible ?')"><?= csrf_field() ?><input type="hidden" name="action" value="convert_submission"><input type="hidden" name="id" value="<?= (int)$submission['id'] ?>"><button class="button button-green">Convertir en fiche publiée ↗</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><p class="admin-empty">Aucune proposition reçue pour le moment.</p><?php endif; ?></section>
  <section class="admin-section"><div class="admin-section-title"><div><span class="eyebrow">RELATION CLIENT</span><h2>Demandes de contact</h2></div></div><?php if ($requests): ?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Client</th><th>Terrain</th><th>Contact</th><th>Message</th><th>État</th><th></th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><?= e($request['nom']) ?><small class="table-sub"> <?= e($request['date_demande']) ?></small></td><td><?= e($request['terrain_titre'] ?? 'Demande générale') ?></td><td><a href="tel:<?= e($request['contact']) ?>"><?= e($request['contact']) ?></a></td><td><?= e($request['message']) ?></td><td><?= e($request['statut']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="request_status"><input type="hidden" name="id" value="<?= (int)$request['id'] ?>"><input type="hidden" name="status" value="<?= $request['statut']==='lu'?'non_lu':'lu' ?>"><button class="text-link">Marquer <?= $request['statut']==='lu'?'non lu':'lu' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="admin-empty">Aucune demande client.</p><?php endif; ?></section>
